topIssues.body:
kona `Hardforks::INTEROP.txs()` unconditionally generates 4 txs (CrossL2Inbox + L2ToL2XDM)

Go's `InteropNetworkUpgradeTransactions()` generates 2 base txs (L2ToL2XDM) and conditionally adds 2 CrossL2Inbox txs when `len(depSet.Chains()) > 1`

on single-chain deployments kona produces 2 spurious CrossL2Inbox txs causing state divergence at Interop activation

`op-node/rollup/derive/attributes.go:163–169`, `op-node/rollup/derive/interop_upgrade_transactions.go:32` 

`optimism/rust/kona/crates/protocol/derive/src/attributes/stateful.rs:164–168`, `optimism/rust/kona/crates/protocol/hardforks/src/interop.rs:87–131` 


And AI that found this by comparing op-node and Kona-node also generated a unit test to confirm this (I have not even read the code or really taught it how to right good tests for these differences so it may or may not be useful):

```rust
// Spec conformance tests for the Attributes Queue (StatefulAttributesBuilder).
//
// Reference: op-node/rollup/derive/attributes.go (PreparePayloadAttributes)
// These tests verify that the kona StatefulAttributesBuilder conforms to the
// op-node reference implementation.

#[cfg(test)]
mod spec_conformance_attributes_queue {
    use crate::{
        AttributesBuilder,
        attributes::StatefulAttributesBuilder,
        errors::{PipelineError, PipelineErrorKind},
        test_utils::{TestChainProvider, TestSystemConfigL2Fetcher},
    };
    use alloc::{sync::Arc, vec, vec::Vec};
    use alloy_consensus::{Eip658Value, Header, Receipt};
    use alloy_eips::BlockNumHash;
    use alloy_primitives::{Address, B256, Bytes, Log, LogData, address, b256};
    use kona_genesis::{
        CONFIG_UPDATE_EVENT_VERSION_0, CONFIG_UPDATE_TOPIC, HardForkConfig, RollupConfig,
        SystemConfig,
    };
    use kona_protocol::{BlockInfo, L2BlockInfo};
    use kona_registry::L1Config;

    // Helper: build a minimal valid L2 parent and matching epoch (same L1 origin)
    fn make_same_epoch_parent(l2_number: u64, l1_hash: B256, l1_number: u64, timestamp: u64) -> (L2BlockInfo, BlockNumHash) {
        let l2_parent = L2BlockInfo {
            block_info: BlockInfo {
                hash: B256::ZERO,
                number: l2_number,
                timestamp,
                parent_hash: B256::ZERO,
            },
            l1_origin: BlockNumHash { hash: l1_hash, number: l1_number },
            seq_num: 0,
        };
        let epoch = BlockNumHash { hash: l1_hash, number: l1_number };
        (l2_parent, epoch)
    }

    // ---------------------------------------------------------------------------
    // AQ-11: Interop CrossL2Inbox activation transactions conditioned on dep-set
    // ---------------------------------------------------------------------------

    /// Reference: op-node/rollup/derive/attributes.go:156–169
    /// Rule AQ-11: At the Interop activation block, the Go reference calls
    ///   InteropNetworkUpgradeTransactions() (L2ToL2XDM deploy + proxy update only). It
    ///   additionally calls InteropActivateCrossL2InboxTransactions() (CrossL2Inbox deploy +
    ///   proxy update) ONLY when len(depSet.Chains()) > 1. The Go comment in
    ///   interop_upgrade_transactions.go line 32 says: "Note that the CrossL2Inbox is not
    ///   deployed here. It is only deployed when the chain is first in a dependency set with
    ///   at least two active chains."
    ///
    /// Finding AQ-11: kona's StatefulAttributesBuilder has no dependency set concept.
    ///   At stateful.rs:164–168, it appends Hardforks::INTEROP.txs() which unconditionally
    ///   includes both CrossL2Inbox AND L2ToL2XDM transactions (4 total). This means:
    ///   - On a single-chain deployment: kona includes CrossL2Inbox txs that Go would omit.
    ///   - On a multi-chain deployment: both include CrossL2Inbox txs (correct).
    ///
    /// NOTE: This test documents the current kona behaviour (always includes CrossL2Inbox txs).
    /// The spec-conformant behaviour would require a dependency set abstraction to make the
    /// CrossL2Inbox transactions conditional.
    #[tokio::test]
    async fn test_spec_attributes_queue_interop_cross_l2_inbox_always_included() {
        // NOTE: Subject (kona) is NOT spec-conformant for single-chain deployments.
        // The Go reference conditionally includes CrossL2Inbox txs based on depSet.Chains() > 1.
        // Kona always includes them (because Hardforks::INTEROP.txs() includes all 4 txs).

        let block_time = 2u64;
        // Set interop_time such that next_l2_time (l2_timestamp + block_time) is the activation block.
        // l2_timestamp = 100, block_time = 2 => next_l2_time = 102
        let l2_timestamp = 100u64;
        let l1_timestamp = 90u64;
        let activation_time = 102u64; // next_l2_time

        let cfg = Arc::new(RollupConfig {
            block_time,
            hardforks: HardForkConfig {
                // Activate all required forks before interop (ecotone, fjord required)
                canyon_time: Some(0),
                ecotone_time: Some(0),
                fjord_time: Some(0),
                interop_time: Some(activation_time),
                ..Default::default()
            },
            ..Default::default()
        });
        let l1_cfg = Arc::new(L1Config::sepolia().into());
        let l2_number = 1u64;
        let l1_number = 1u64;

        let mut fetcher = TestSystemConfigL2Fetcher::default();
        fetcher.insert(l2_number, SystemConfig::default());

        // Build a valid L1 header (timestamp must be <= next_l2_time to pass time invariant)
        let l1_header = Header { timestamp: l1_timestamp, ..Default::default() };
        let l1_hash = l1_header.hash_slow();

        let mut provider = TestChainProvider::default();
        provider.insert_header(l1_hash, l1_header);

        // Same epoch (l1_origin.number == epoch.number), no deposit fetch needed
        let (l2_parent, epoch) = make_same_epoch_parent(l2_number, l1_hash, l1_number, l2_timestamp);

        let mut builder = StatefulAttributesBuilder::new(cfg, l1_cfg, fetcher, provider);
        let attrs = builder.prepare_payload_attributes(l2_parent, epoch).await.unwrap();

        let txs = attrs.transactions.as_ref().expect("transactions must be Some at interop activation");

        // Count transactions: 1 (L1 info) + 4 (INTEROP: CrossL2Inbox x2 + L2ToL2XDM x2)
        // The Go reference on a single-chain deployment would produce:
        //   1 (L1 info) + 2 (L2ToL2XDM only from InteropNetworkUpgradeTransactions)
        // Kona produces 5 total because Hardforks::INTEROP.txs() includes all 4.
        assert_eq!(
            txs.len(),
            5,
            "kona unconditionally includes 4 Interop upgrade txs (CrossL2Inbox + L2ToL2XDM); \
             Go reference would include only 2 for a single-chain deployment"
        );

        // Verify the discrepancy: Go on single-chain would produce 3 txs (1 L1 info + 2 L2ToL2XDM).
        // This assertion documents what the spec-correct single-chain count should be:
        let go_single_chain_count = 3usize;
        assert_ne!(
            txs.len(),
            go_single_chain_count,
            "kona tx count ({}) matches Go single-chain count ({}) unexpectedly",
            txs.len(),
            go_single_chain_count
        );
    }
}
```
